import { readFile, writeFile } from 'node:fs/promises';
import wordListPath from 'word-list';

// Generate a runtime-independent module for the Worker (no filesystem at runtime).
const words = [...new Set((await readFile(wordListPath, 'utf8')).split(/\r?\n/))]
  .filter((word) => /^[a-z]{2,40}$/.test(word));
const license = await readFile(new URL('../node_modules/word-list/license', import.meta.url), 'utf8');
await writeFile(
  new URL('../lib/words/en/pattern-dictionary.js', import.meta.url),
  '// Generated by scripts/prepare-pattern-dictionary.mjs from word-list 4.1.0 (MIT).\n' +
    '/*\n' + license + '\n*/\n' +
    'export const patternDictionary = ' + JSON.stringify(words.join('\n')) + ';\n',
);
console.log(`Generated ${words.length} dictionary words.`);
